From 1b1d3bd77237ac574e3d5c8f4c3cc50bdadac76a Mon Sep 17 00:00:00 2001
From: Thomas Knudsen <thokn@sdfe.dk>
Date: Fri, 13 Oct 2017 11:40:56 +0200
Subject: [PATCH] OSS-Fuzz issue 3630: Missing return in PJ_lsat.c

Resolves https://bugs.chromium.org/p/oss-fuzz/issues/detail?id=3630

Credit to OSS-Fuzz
---
 src/PJ_lsat.c | 2 +-
 1 file changed, 1 insertion(+), 1 deletion(-)

diff --git a/src/PJ_lsat.c b/src/PJ_lsat.c
index 1b3778d..7319bee 100644
--- a/src/PJ_lsat.c
+++ b/src/PJ_lsat.c
@@ -163,7 +163,7 @@ PJ *PROJECTION(lsat) {

     path = pj_param(P->ctx, P->params, "ipath").i;
     if (path <= 0 || path > (land <= 3 ? 251 : 233))
-        pj_default_destructor(P, PJD_ERR_PATH_NOT_IN_RANGE);
+        return pj_default_destructor(P, PJD_ERR_PATH_NOT_IN_RANGE);

     if (land <= 3) {
         P->lam0 = DEG_TO_RAD * 128.87 - M_TWOPI / 251. * path;
